-- H2 内存库建表脚本（unit-test profile）
-- 注：Spring ScriptUtils 不能执行纯注释脚本，故保留一条无害语句占位
SELECT 1;

-- 智能体规格表（spec_code 唯一性由应用层预校验保证——生产库部分唯一索引为 PG 方言，H2 不建）
CREATE TABLE IF NOT EXISTS "ai_agent_spec" (
    "id"            bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"          varchar(64)  NOT NULL,
    "spec_code"     varchar(64)  NOT NULL,
    "icon"          varchar(128) DEFAULT NULL,
    "owner_level"   varchar(16)  NOT NULL DEFAULT 'TENANT',
    "owner_user_id" bigint       DEFAULT NULL,
    "draft"         text         DEFAULT NULL,
    "current_version_no" int    DEFAULT NULL,
    "creator"       varchar(64)  DEFAULT '',
    "create_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar(64)  DEFAULT '',
    "update_time"   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit          NOT NULL DEFAULT 0,
    "tenant_id"     bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台智能体规格表（行为性配置全在 draft JSON 内，随版本快照固化；主体列只留管理元数据）';

-- 智能体规格版本快照表（不可变：只插不改不删；版本号唯一性由应用层 max+1 计算保证——唯一索引为 PG 方言，H2 不建）
CREATE TABLE IF NOT EXISTS "ai_agent_spec_version" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "spec_id"     bigint       NOT NULL,
    "version_no"  int          NOT NULL,
    "config"      text         NOT NULL,
    "note"        varchar(255) DEFAULT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台智能体规格版本快照表（不可变：只插不改不删；版本按规格聚合，租户归属继承自规格）';

CREATE TABLE IF NOT EXISTS "ai_channel" (
    "id"         bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"       varchar(64)  NOT NULL,
    "provider"   varchar(32)  NOT NULL,
    "base_url"   varchar(512) NOT NULL,
    "api_key"    varchar(1024) DEFAULT NULL,
    "enabled"    bit          NOT NULL DEFAULT 1,
    "owner_type" varchar(16)  NOT NULL DEFAULT 'tenant',
    "creator"    varchar(64)  DEFAULT '',
    "create_time" datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"    varchar(64)  DEFAULT '',
    "update_time" datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"    bit          NOT NULL DEFAULT 0,
    "tenant_id"  bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台模型渠道表（api_key 经 EncryptTypeHandler AES 密文落库；归属 MVP 固定 tenant）';

CREATE TABLE IF NOT EXISTS "ai_model" (
    "id"              bigint         NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "channel_id"      bigint         NOT NULL,
    "model_id"        varchar(128)   NOT NULL,
    "name"            varchar(64)    NOT NULL,
    "context_window"  int            DEFAULT NULL,
    "input_price"     decimal(12, 6) DEFAULT NULL,
    "output_price"    decimal(12, 6) DEFAULT NULL,
    "enabled"         bit            NOT NULL DEFAULT 1,
    "creator"         varchar(64)    DEFAULT '',
    "create_time"     datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)    DEFAULT '',
    "update_time"     datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit            NOT NULL DEFAULT 0,
    "tenant_id"       bigint         NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台模型元数据表（挂接渠道；channel_id+model_id 唯一性由应用层预校验+生产库唯一索引保证）';

-- 调试会话表（session_key 全局唯一；rounds 轮次 JSON、pending_confirmations HITL 挂起上下文）
CREATE TABLE IF NOT EXISTS "ai_session" (
    "id"                  bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "session_key"         varchar(64)  NOT NULL,
    "title"               varchar(128) NOT NULL,
    "type"                varchar(16)  NOT NULL DEFAULT 'DEBUG',
    "user_id"             bigint       DEFAULT NULL,
    "spec_id"             bigint       NOT NULL,
    "version_no"          int          DEFAULT NULL,
    "status"              varchar(16)  NOT NULL DEFAULT 'READY',
    "rounds"              text         NOT NULL DEFAULT '[]',
    "pending_confirmations" text       DEFAULT NULL,
    "creator"             varchar(64)  DEFAULT '',
    "create_time"         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"             varchar(64)  DEFAULT '',
    "update_time"         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"             bit          NOT NULL DEFAULT 0,
    "tenant_id"           bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台调试会话表（智能体状态由 agentscope 状态存储管理，本表只存平台侧会话元数据）';

-- Skill 资产表（能力包内容随版本链存 ai_skill_version）
CREATE TABLE IF NOT EXISTS "ai_skill" (
    "id"                 bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"               varchar(255) NOT NULL,
    "description"        varchar(512) NOT NULL,
    "owner_level"        varchar(16)  NOT NULL DEFAULT 'TENANT',
    "owner_user_id"      bigint       DEFAULT NULL,
    "current_version_no" int          DEFAULT NULL,
    "published"          int          NOT NULL DEFAULT 0,
    "git_source_id"      bigint       DEFAULT NULL,
    "creator"            varchar(64)  DEFAULT '',
    "create_time"        datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"            varchar(64)  DEFAULT '',
    "update_time"        datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"            bit          NOT NULL DEFAULT 0,
    "tenant_id"          bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台 Skill 资产表（能力包内容随版本链存 ai_skill_version）';

-- Skill 版本表（不可变：只插不改不删）
CREATE TABLE IF NOT EXISTS "ai_skill_version" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "skill_id"    bigint       NOT NULL,
    "version_no"  int          NOT NULL,
    "content"     text         NOT NULL,
    "note"        varchar(255) DEFAULT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台 Skill 版本表（能力包内容：markdown + resources，不可变）';

-- MCP Server 表（BYO-MCP：三传输/认证/工具白名单，工单 11）
CREATE TABLE IF NOT EXISTS "ai_mcp_server" (
    "id"              bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"            varchar(64)  NOT NULL,
    "transport"       varchar(32)  NOT NULL,
    "endpoint"        varchar(512) DEFAULT NULL,
    "command"         varchar(255) DEFAULT NULL,
    "args"            text         DEFAULT NULL,
    "env"             text         DEFAULT NULL,
    "headers"         text         DEFAULT NULL,
    "timeout_seconds" int          DEFAULT NULL,
    "allowed_tools"   text         DEFAULT NULL,
    "available_tools" text         DEFAULT NULL,
    "enabled"         bit          NOT NULL DEFAULT 1,
    "owner_type"      varchar(16)  NOT NULL DEFAULT 'tenant',
    "creator"         varchar(64)  DEFAULT '',
    "create_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)  DEFAULT '',
    "update_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"         bit          NOT NULL DEFAULT 0,
    "tenant_id"       bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台 MCP Server 表（args/env/headers/白名单为 JSON；headers 密文，工单 11）';


-- 审计事件表（append-only：谁-何时-哪个会话-调了什么工具-结果摘要，工单 14）
CREATE TABLE IF NOT EXISTS "ai_audit_event" (
    "id"               bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "session_key"      varchar(64)  NOT NULL,
    "spec_id"          bigint       DEFAULT NULL,
    "version_no"       int          DEFAULT NULL,
    "agent_id"         varchar(64)  DEFAULT NULL,
    "user_id"          varchar(64)  DEFAULT NULL,
    "tool_call_id"     varchar(128) DEFAULT NULL,
    "tool_name"        varchar(128) NOT NULL,
    "outcome"          varchar(16)  NOT NULL,
    "arguments_digest" text         DEFAULT NULL,
    "result_digest"    text         DEFAULT NULL,
    "duration_ms"      bigint       DEFAULT NULL,
    "occurred_at"      datetime     NOT NULL,
    "creator"          varchar(64)  DEFAULT '',
    "create_time"      datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"          varchar(64)  DEFAULT '',
    "update_time"      datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"          bit          NOT NULL DEFAULT 0,
    "tenant_id"        bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台审计事件表（入参/结果为脱敏摘要，工单 14）';

-- 模型用量表（append-only：单次模型调用 token/缓存命中/耗时，工单 14）
CREATE TABLE IF NOT EXISTS "ai_model_usage" (
    "id"               bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "session_key"      varchar(64)  NOT NULL,
    "spec_id"          bigint       DEFAULT NULL,
    "version_no"       int          DEFAULT NULL,
    "agent_id"         varchar(64)  DEFAULT NULL,
    "user_id"          varchar(64)  DEFAULT NULL,
    "model_name"       varchar(256) NOT NULL,
    "message_count"    int          DEFAULT NULL,
    "input_tokens"     int          DEFAULT NULL,
    "output_tokens"    int          DEFAULT NULL,
    "cached_tokens"    int          DEFAULT NULL,
    "total_tokens"     int          DEFAULT NULL,
    "duration_seconds" double       DEFAULT NULL,
    "occurred_at"      datetime     NOT NULL,
    "creator"          varchar(64)  DEFAULT '',
    "create_time"      datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"          varchar(64)  DEFAULT '',
    "update_time"      datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"          bit          NOT NULL DEFAULT 0,
    "tenant_id"        bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台模型用量表（先采集不计价，工单 14）';


-- 租户 API Key 表（密文存储：SHA-256 哈希 + 识别前缀，工单 16）
CREATE TABLE IF NOT EXISTS "ai_tenant_api_key" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar(64)  NOT NULL,
    "key_prefix"  varchar(32)  NOT NULL,
    "key_hash"    varchar(64)  NOT NULL,
    "status"      varchar(16)  NOT NULL DEFAULT 'ENABLED',
    "spec_codes"  text         DEFAULT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台租户 API Key 表（OpenAI 兼容出口凭证，密文存储）';
